const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number(n).toLocaleString(undefined,{maximumFractionDigits:2});
const example=[{name:'Matrix analytics',cost:6,benefit:10,priority:3},{name:'Image batch',cost:5,benefit:9,priority:2},{name:'Data processing',cost:4,benefit:8,priority:5}];
let current=null,records=[],index=new Algorithms.BTree(),storageWarning='';
try{const raw=JSON.parse(localStorage.getItem('thermal-simple-v1')||'[]');if(!Array.isArray(raw)||raw.some(r=>!Number.isInteger(r.id)||typeof r.html!=='string'||typeof r.type!=='string'))throw Error();records=raw.slice(-200);}catch{storageWarning='Browser history is unavailable or unreadable. This session still works; download results to keep them.';}
function notify(s){$('message').textContent=s;}
function historyList(){index=new Algorithms.BTree();for(const r of records)index.insert(r.id,r);$('saved').innerHTML=records.length?[...records].reverse().map(r=>`<option value="${r.id}">#${r.id} · ${esc(r.type)} · ${esc(r.time)}</option>`).join(''):'<option value="">No saved results yet</option>';}
function save(type,data,html){const r={id:Math.max(0,...records.map(x=>x.id))+1,type,time:new Date().toLocaleString(),data,html};records.push(r);records=records.slice(-200);historyList();try{localStorage.setItem('thermal-simple-v1',JSON.stringify(records));}catch{notify('Result available for this session only: browser storage is full or disabled. Use Download results to keep it.');}}
function guarded(fn){return()=>{notify('');try{fn();}catch(e){notify(e.message);}};}
function row(j){const tr=document.createElement('tr');tr.innerHTML=`<td><input aria-label="Task name" value="${esc(j.name)}" maxlength="60"></td>${['cost','benefit','priority'].map(k=>`<td><input aria-label="${k}" type="number" value="${j[k]}" min="${k==='benefit'?0:1}"></td>`).join('')}<td><button aria-label="Remove task">×</button></td>`;tr.querySelector('button').onclick=()=>{tr.remove();invalidate();};$('jobs').append(tr);}
function invalidate(){current=null;$('selection').className='result empty';$('selection').textContent='Inputs changed. Choose best tasks to update the result.';$('queue').className='result empty';$('queue').textContent='Choose tasks in step 1 to update this queue.';$('priorityresult').innerHTML='';$('urgent').innerHTML='<option value="">No priority change</option>';}
function reset(){ $('jobs').innerHTML='';example.forEach(row);$('budget').value=9;$('partial').checked=false;invalidate();}
function readJobs(){return [...$('jobs').rows].map(tr=>{const v=[...tr.querySelectorAll('input')].map(x=>x.value.trim());if(v.some(x=>x===''))throw Error('Fill in every task field.');return {name:v[0],cost:Number(v[1]),benefit:Number(v[2]),priority:Number(v[3])};});}
function chips(order){return '<div class="order">'+order.map((j,i)=>`<div class="taskchip"><b>${i+1}. ${i===0?'First':'Next'}</b>${esc(j.item)} <small>priority ${j.key}</small></div>`).join('')+'</div>';}
function buildQueue(){const results=Algorithms.priorities(current.result.chosen,null),order=results[0].order;$('queue').className='result';$('queue').innerHTML='<h3>Before any change</h3>'+ (order.length?chips(order):'<p>No tasks admitted. Increase the budget or change your tasks.</p>');$('urgent').innerHTML='<option value="">No priority change</option>'+order.slice(1).map(j=>`<option value="${esc(j.item)}">${esc(j.item)}</option>`).join('');if(order.slice(1).some(j=>j.item==='Data processing'))$('urgent').value='Data processing';$('priorityresult').innerHTML='';}
$('choose').onclick=guarded(()=>{const jobs=readJobs();if(!$('budget').value.trim())throw Error('Enter a budget.');const W=Number($('budget').value),partial=$('partial').checked,start=performance.now(),r=Algorithms.knapsack(jobs,W,partial),ms=performance.now()-start;current={jobs,W,partial,result:r};const html=`<h3>${r.algorithm}</h3><div class="stats"><div><strong>${fmt(r.benefit)}</strong><span>Total benefit</span></div><div><strong>${fmt(r.cost)} / ${W}</strong><span>Resource units used</span></div></div>${r.chosen.length?'<div class="tablewrap"><table><thead><tr><th>Selected task</th><th>Portion</th><th>Cost</th><th>Benefit</th></tr></thead><tbody>'+r.chosen.map(j=>`<tr><td>${esc(j.name)}</td><td>${fmt(j.share*100)}%</td><td>${fmt(j.cost*j.share)}</td><td>${fmt(j.benefit*j.share)}</td></tr>`).join('')+'</tbody></table></div>':'<p>No complete tasks fit this budget.</p>'}<p style="margin-top:15px">${partial?'Partial work is allowed, so we choose the highest benefit per unit first.':'Whole tasks only: we choose the combination giving the highest total benefit within the budget.'}</p><details><summary>Algorithm details</summary><p>${partial?'Greedy Fractional Knapsack · O(n log n) time · O(n) space.':'Dynamic programming 0/1 Knapsack · O(nW) time and space.'} Measured selection time: ${ms.toFixed(4)} ms. ${r.steps} ${partial?'allocation steps (sorting excluded)':'DP cells evaluated'}.</p></details>`;$('selection').className='result';$('selection').innerHTML=html;buildQueue();save('Task selection',{jobs,budget:W,partial,...r,ms},html);});
$('optimize').onclick=guarded(()=>{const text=$('dims').value.split(',');if(text.some(x=>!x.trim()))throw Error('Enter all matrix dimensions.');const dims=text.map(Number),start=performance.now(),r=Algorithms.matrix(dims),ms=performance.now()-start,saved=r.baseline-r.optimal,pct=r.baseline?100*saved/r.baseline:0;const html=`<h3>${fmt(pct)}% fewer multiplications</h3><p>Dimensions used: ${dims.join(', ')}</p><div class="stats"><div><strong>${fmt(r.baseline)}</strong><span>Before · left-to-right grouping</span></div><div><strong>${fmt(r.optimal)}</strong><span>After · optimal grouping</span></div><div><strong>${fmt(saved)}</strong><span>Multiplications avoided</span></div></div><p><b>Better grouping: ${esc(r.order)}</b></p><p>Same matrix sequence and mathematical result. This measures calculation savings, not temperature savings.</p><details><summary>Algorithm details</summary><p>Matrix Chain Multiplication · Dynamic programming · O(m³) time, O(m²) space. ${r.steps} candidate splits. Planner time: ${ms.toFixed(4)} ms. Matrix entries are not multiplied by this prototype; operation counts are calculated from dimensions.</p></details>`;$('matrixresult').className='result';$('matrixresult').innerHTML=html;save('Matrix optimization',{dims,...r,ms},html);});
$('reorder').onclick=guarded(()=>{if(!current)throw Error('First choose tasks in step 1.');const urgent=$('urgent').value,results=Algorithms.priorities(current.result.chosen,urgent);const html=`<h3>${urgent?'Urgent task moved forward':'Dispatch order'}</h3><p>${urgent?'The first task was already dispatched. '+esc(urgent)+' then becomes priority 0 (urgent) and moves ahead of other waiting tasks.':'No priority change was requested.'}</p>${chips(results[0].order)}<p><b>Both heaps process the same admitted tasks.</b> Equal-priority ties can have different valid orders.</p><details><summary>Compare the two heaps</summary><div class="tablewrap"><table><thead><tr><th>Structure</th><th>Time (ms)</th><th>Links</th><th>Cuts</th><th>Swaps</th></tr></thead><tbody>${results.map(r=>`<tr><td>${r.name}</td><td>${r.ms.toFixed(4)}</td><td>${r.links}</td><td>${r.cuts}</td><td>${r.swaps}</td></tr>`).join('')}</tbody></table></div>${results.map(r=>`<p>${r.name}: ${r.order.map(j=>esc(j.item)).join(' → ')}</p>`).join('')}<p>Timings vary between runs. A link, cut and swap are different operations, not equal measures of CPU work.</p></details>`;$('priorityresult').className='result';$('priorityresult').innerHTML=html;save('Priority update',{urgent,admitted:current.result.chosen,results},html);});
// Saved HTML is generated here. Display it in a sandboxed iframe to prevent any
// modified browser-storage content from running scripts or escaping into the app.
$('find').onclick=guarded(()=>{const r=index.search(Number($('saved').value));if(!r)throw Error('Choose a saved result first.');$('historyresult').className='result';$('historyresult').replaceChildren();const title=document.createElement('h3');title.textContent=`Found #${r.id} · ${r.type} using B-Tree`;const frame=document.createElement('iframe');frame.title='Saved result';frame.setAttribute('sandbox','');frame.style='width:100%;height:420px;border:0;background:white;border-radius:8px';frame.srcdoc='<meta charset="utf-8"><style>body{font:15px/1.6 system-ui;color:#153c38;padding:12px}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:8px;border-bottom:1px solid #ddd}.stats{display:flex;gap:25px;margin:20px 0}.stats strong{display:block;font-size:26px}.order{display:flex;flex-wrap:wrap;gap:12px}.taskchip{padding:10px;border:1px solid #ddd}.taskchip b{display:block}</style>'+r.html;$('historyresult').append(title,frame);});
$('export').onclick=guarded(()=>{if(!records.length)throw Error('Run one demonstration before downloading results.');const blob=new Blob([JSON.stringify(records.map(({html,...r})=>r),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cpu-planner-results.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{for(const p of document.querySelectorAll('.panel'))p.hidden=p.id!==b.dataset.tab;for(const n of document.querySelectorAll('[data-tab]'))n.classList.toggle('active',n===b);notify('');};
$('reset').onclick=reset;$('add').onclick=guarded(()=>{if($('jobs').rows.length>=100)throw Error('Maximum 100 tasks.');row({name:'Task '+($('jobs').rows.length+1),cost:1,benefit:1,priority:10});invalidate();});$('jobs').addEventListener('input',invalidate);$('budget').oninput=invalidate;$('partial').onchange=invalidate;$('help').onclick=()=>$('helpdialog').showModal();$('closehelp').onclick=()=>$('helpdialog').close();historyList();reset();if(storageWarning)notify(storageWarning);
